const fs=require('fs'),assert=require('assert/strict'),R=require('node:path').resolve(__dirname,'../../..');const {avecJeu,page}=require(R+'/outils/bancs/mobile-navigateur.cjs');const langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
(async()=>avecJeu(async(browser,o)=>{for(const width of [320,390]){const p=await page(browser,o,width,568,false,{texteMinimum:true});await p.addScriptTag({content:`var state={pa:50,arg:100};window.RP_I18N_GAME_ENABLED=true;var calls=0;window.sbRpc=async(fn)=>{calls++;return fn==='universite_mon_etat'?{ok:true,cursus_disponibles:['droit_penal','medecin','affaires','justice','armee'].map(k=>({id:'univ_'+k,libelle:RPUniversityI18n.words.fr['c_univ_'+k],carriere_libelle:'Profession du serveur',semaines_theoriques:4}))}:{ok:true,etape:null};};`});for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/plateau-bridge.js','i18n/plateau-init.js','plateau-universite.js'])await p.addScriptTag({url:o+'/'+f});await p.waitForFunction(()=>!!window.RPUniversityI18n);await p.evaluate(()=>ouvrirUniversiteFormation());const calls=await p.evaluate(()=>window.calls);for(const l of langs){await p.evaluate(l=>i18next.changeLanguage(l),l);const close=p.locator('[data-university-root] button').last();await close.scrollIntoViewIfNeeded();const b=await close.boundingBox();assert.ok(b.y>=0&&b.y+b.height<=569,JSON.stringify({width,l,b}));assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await p.evaluate(()=>window.calls),calls);}await p.locator('[data-university-root] button').last().click();assert.equal(await p.locator('#modal-postes').evaluate(n=>n.classList.contains('open')),false);await p.close();}console.log('320×568 et 390×568 : neuf langues, fermeture accessible après défilement, aucun débordement horizontal ni RPC supplémentaire.');}))().catch(e=>{console.error(e);process.exitCode=1;});
